package com.deckscape.runelite.ui;

import com.deckscape.runelite.DeckscapeStore;
import com.deckscape.runelite.model.DeckscapeState;
import java.awt.Component;
import java.awt.Container;
import java.lang.reflect.Field;
import java.util.concurrent.atomic.AtomicReference;
import javax.swing.JScrollPane;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.laf.RuneLiteScrollBarUI;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNotSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

class DeckscapePanelLayoutTest
{
    @Test
    void usesRuneLiteScrollablePanelWrapper() throws Exception
    {
        DeckscapeStore store = new DeckscapeStore(null, null);
        Field stateField = DeckscapeStore.class.getDeclaredField("state");
        stateField.setAccessible(true);
        stateField.set(store, new DeckscapeState());

        AtomicReference<DeckscapePanel> reference = new AtomicReference<>();
        SwingUtilities.invokeAndWait(() -> reference.set(new DeckscapePanel(store)));
        DeckscapePanel panel = reference.get();

        assertNotSame(panel, panel.getWrappedPanel());
        JScrollPane scrollPane = findScrollPane(panel.getWrappedPanel());
        assertNotNull(scrollPane);
        assertEquals(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER, scrollPane.getHorizontalScrollBarPolicy());
        assertEquals(16, scrollPane.getVerticalScrollBar().getUnitIncrement());
        assertEquals(RuneLiteScrollBarUI.class, scrollPane.getVerticalScrollBar().getUI().getClass());
        assertEquals(ColorScheme.DARK_GRAY_COLOR, scrollPane.getViewport().getBackground());
        assertEquals(ColorScheme.SCROLL_TRACK_COLOR, scrollPane.getVerticalScrollBar().getBackground());

        JLabel featureCopy = findLabel(panel, "Use the cards you earn here");
        assertNotNull(featureCopy);
        assertTrue(featureCopy.getPreferredSize().width <= 165);
    }

    private static JScrollPane findScrollPane(Container root)
    {
        for (Component component : root.getComponents())
        {
            if (component instanceof JScrollPane) return (JScrollPane) component;
            if (component instanceof Container)
            {
                JScrollPane nested = findScrollPane((Container) component);
                if (nested != null) return nested;
            }
        }
        return null;
    }

    private static JLabel findLabel(Container root, String text)
    {
        for (Component component : root.getComponents())
        {
            if (component instanceof JLabel && ((JLabel) component).getText().contains(text))
                return (JLabel) component;
            if (component instanceof Container)
            {
                JLabel nested = findLabel((Container) component, text);
                if (nested != null) return nested;
            }
        }
        return null;
    }
}

package com.deckscape.runelite.ui;

import com.deckscape.runelite.model.DeckscapeState;
import com.deckscape.runelite.model.PendingSyncEvent;
import com.google.gson.JsonObject;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;

class XpProgressSnapshotTest
{
    @Test
    void includesQueuedXpInBothLiveProgressCounters()
    {
        DeckscapeState state = new DeckscapeState();
        state.setXpTowardsPack(29_000);
        state.setXpTowardsCurrency(3_000);
        JsonObject payload = new JsonObject();
        payload.addProperty("xp", 934);
        state.getPendingEvents().add(new PendingSyncEvent("runelite_xp", "event-id", payload));

        XpProgressSnapshot progress = XpProgressSnapshot.from(state);

        assertEquals(29_934, progress.getPackProgress());
        assertEquals(59, progress.getPackPercent());
        assertEquals(3_934, progress.getCurrencyProgress());
        assertEquals(39, progress.getCurrencyPercent());
    }

    @Test
    void wrapsProgressAfterCrossingEachRewardInterval()
    {
        DeckscapeState state = new DeckscapeState();
        state.setXpTowardsPack(49_900);
        state.setXpTowardsCurrency(9_900);
        JsonObject payload = new JsonObject();
        payload.addProperty("xp", 250);
        state.getPendingEvents().add(new PendingSyncEvent("runelite_xp", "event-id", payload));

        XpProgressSnapshot progress = XpProgressSnapshot.from(state);

        assertEquals(150, progress.getPackProgress());
        assertEquals(150, progress.getCurrencyProgress());
        assertEquals(0, progress.getPackPercent());
        assertEquals(1, progress.getCurrencyPercent());
    }
}

package com.deckscape.runelite.ui;

import com.deckscape.runelite.model.CardCatalog;
import com.deckscape.runelite.model.DeckscapeCard;
import com.deckscape.runelite.model.PackType;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.File;
import javax.imageio.ImageIO;
import org.junit.jupiter.api.Test;

/** Temporary visual harness: renders the painters to PNGs for manual inspection. */
class RenderPreviewTest
{
    private static final File OUT = new File(System.getProperty("deckscape.preview.dir", "build/preview"));

    @Test
    void renderPreviews() throws Exception
    {
        OUT.mkdirs();
        face("face_grayzag", CardCatalog.byId("wizard_grayzag"), 3, 200, 300);
        face("face_goblin_mail", CardCatalog.byId("goblin_mail"), 0, 200, 300);
        face("face_imp", CardCatalog.byId("imp"), 0, 200, 300);
        face("face_casket", CardCatalog.byId("casket"), 0, 200, 300);
        face("face_magic_ball", CardCatalog.byId("magic_ball"), 0, 200, 300);
        face("face_smite_universal", CardCatalog.byId("smite"), 2, 200, 300);
        face("face_small_tile", CardCatalog.byId("archmage_sedridor"), 1, 124, 186);
        collectionFace("face_kandarin_collection", new DeckscapeCard("demonic_gorilla", "Demonic Gorilla", "Kandarin",
            DeckscapeCard.Rarity.EPIC, DeckscapeCard.Kind.UNIT, DeckscapeCard.Style.MELEE, 10, 9, "", null), 2, 200);
        collectionFace("face_varlamore_collection", new DeckscapeCard("blood_moon", "Blood Moon", "Varlamore",
            DeckscapeCard.Rarity.RARE, DeckscapeCard.Kind.UNIT, DeckscapeCard.Style.MELEE, 9, 9, "", null), 3, 200);
        collectionTile("face_unowned", CardCatalog.byId("wizard_grayzag"), 0, 200);

        back("back_misthalin", "Misthalin");
        back("back_universal", "Universal");

        ImageIO.write(CardPainter.packImage(PackType.SKILLING, 132, 190), "png", new File(OUT, "pack_skilling.png"));
        ImageIO.write(CardPainter.packImage(PackType.GENERAL, 132, 190), "png", new File(OUT, "pack_general.png"));
        ImageIO.write(CardPainter.packImage(PackType.FACTION_MISTHALIN, 132, 190), "png", new File(OUT, "pack_misthalin.png"));
    }

    private static void face(String name, DeckscapeCard card, int owned, int w, int h) throws Exception
    {
        BufferedImage image = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        CardPainter.paintFace(g, 0, 0, w, h, card, owned);
        g.dispose();
        ImageIO.write(image, "png", new File(OUT, name + ".png"));
    }

    private static void back(String name, String faction) throws Exception
    {
        BufferedImage image = new BufferedImage(200, 300, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        CardPainter.paintBack(g, 0, 0, 200, 300, faction);
        g.dispose();
        ImageIO.write(image, "png", new File(OUT, name + ".png"));
    }

    private static void collectionFace(String name, DeckscapeCard card, int owned, int width) throws Exception
    {
        int cardHeight = CardTile.cardHeightForWidth(width);
        BufferedImage image = new BufferedImage(width, CardTile.collectionHeightForWidth(width), BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        CardPainter.paintFace(g, 0, 0, width, cardHeight, card, owned);
        g.dispose();
        ImageIO.write(image, "png", new File(OUT, name + ".png"));
    }

    private static void collectionTile(String name, DeckscapeCard card, int owned, int width) throws Exception
    {
        CardTile tile = new CardTile(card, owned);
        tile.setSize(width, CardTile.collectionHeightForWidth(width));
        BufferedImage image = new BufferedImage(tile.getWidth(), tile.getHeight(), BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        tile.paint(g);
        g.dispose();
        ImageIO.write(image, "png", new File(OUT, name + ".png"));
    }
}

package com.deckscape.runelite.ui;

import com.deckscape.runelite.model.DeckscapeCard;
import java.util.List;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

class DeckscapeImagesTest
{
    @Test
    void keepsDirectWikiImageUrlsAndAddsNameFallbacks()
    {
        String direct = "https://oldschool.runescape.wiki/w/Special:FilePath/Quetzal_Whistle.png";
        List<String> candidates = DeckscapeImages.remoteCandidates("Quetzal Whistle", direct);

        assertEquals(direct, candidates.get(0));
        assertTrue(candidates.contains("https://oldschool.runescape.wiki/w/Special:FilePath/Quetzal_Whistle_detail.png"));
    }

    @Test
    void convertsWikiMediaFragmentsToDirectFileRequests()
    {
        List<String> candidates = DeckscapeImages.remoteCandidates("Ernest (Chicken)",
            "https://oldschool.runescape.wiki/w/Ernest_the_Chicken#/media/File:Chicken_(Ernest).png");

        assertTrue(candidates.get(0).contains("Special:FilePath/Chicken_%28Ernest%29.png"));
    }

    @Test
    void rejectsNonWikiHosts()
    {
        List<String> candidates = DeckscapeImages.remoteCandidates("Pygmy Hippo Call",
            "https://example.com/tracker/card.png");

        assertEquals(2, candidates.size());
        assertTrue(candidates.get(0).startsWith("https://oldschool.runescape.wiki/w/Special:FilePath/"));
    }

    @Test
    void bundlesEveryWebRegionBackdrop()
    {
        for (String faction : new String[] {"Misthalin", "Karamja", "Asgarnia", "Kandarin", "Fremennik",
            "Morytania", "Desert", "Tirannwn", "Wilderness", "Kourend", "Varlamore", "Universal"})
        {
            RegionTheme theme = RegionTheme.forFaction(faction);
            assertNotNull(theme.backdrop, faction);
            assertNotNull(DeckscapeImages.load(theme.backdrop), faction);
        }
    }

    @Test
    void loadsWebBundledArtForServerCatalogCards()
    {
        DeckscapeCard card = new DeckscapeCard("demonic_gorilla", "Demonic Gorilla", "Kandarin",
            DeckscapeCard.Rarity.EPIC, DeckscapeCard.Kind.UNIT, DeckscapeCard.Style.MELEE,
            10, 9, "", null, null);

        assertNotNull(DeckscapeImages.loadCardArt(card));
    }
}

package com.deckscape.runelite;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class DeckscapePluginTest
{
