        label.setForeground(DeckscapePalette.PARCHMENT);
        label.setFont(new Font("SansSerif", Font.PLAIN, 10));
        return label;
    }

    private static JLabel progressPercentLabel(Color color)
    {
        JLabel label = new JLabel("0%", SwingConstants.RIGHT);
        label.setForeground(color);
        label.setFont(new Font("SansSerif", Font.BOLD, 10));
        return label;
    }

    private static JProgressBar progressBar(Color color)
    {
        JProgressBar bar = new JProgressBar(0, 100);
        bar.setValue(0);
        bar.setForeground(color);
        bar.setBackground(new Color(48, 48, 43));
        bar.setBorder(BorderFactory.createEmptyBorder());
        bar.setAlignmentX(LEFT_ALIGNMENT);
        bar.setMaximumSize(new Dimension(Integer.MAX_VALUE, 8));
        bar.setPreferredSize(new Dimension(100, 8));
        return bar;
    }

    private void showDialog(DeckscapeDialog.Tab tab)
    {
        Frame frame = (Frame) SwingUtilities.getWindowAncestor(this);
        if (dialog == null || !dialog.isDisplayable())
            dialog = new DeckscapeDialog(frame, store, openPackAction, purchasePackAction, syncAction, soundPlayer);
        dialog.showTab(tab);
        dialog.setVisible(true);
    }

    private void copyPairingCode()
    {
        String code = store.load().getPairingCode();
        if (!code.isEmpty()) Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(code), null);
    }

    public void refresh()
    {
        SwingUtilities.invokeLater(() -> {
            DeckscapeState state = store.load();
            if (state.isLinked())
            {
                statusLabel.setText("● Connected to Deckscape");
                statusLabel.setForeground(new Color(111, 204, 120));
            }
            else
            {
                statusLabel.setText("● Waiting for account link");
                statusLabel.setForeground(new Color(236, 184, 79));
            }
            String lastSync = state.getLastSyncAt() <= 0 ? "Not synchronized yet"
                : "Last sync " + new SimpleDateFormat("HH:mm:ss").format(new Date(state.getLastSyncAt()));
            if (!state.getPendingEvents().isEmpty()) lastSync += " · " + state.getPendingEvents().size() + " queued";
            syncDetail.setText(lastSync);
            syncNowButton.setEnabled(state.isLinked());
            codeField.setText(state.getPairingCode().isEmpty() ? "CLICK NEW CODE" : state.getPairingCode());
            pairingBox.setVisible(!state.isLinked());
            int packs = java.util.Arrays.stream(PackType.inventoryTypes()).mapToInt(state::packCount).sum();
            long uniqueCards = CardCatalog.all().stream()
                .filter(card -> state.getCollection().getOrDefault(card.getId(), 0) > 0)
                .count();
            coinsLabel.setText(String.valueOf(state.getCoins()));
            stardustLabel.setText(String.valueOf(state.getStardust()));
            packsLabel.setText(String.valueOf(packs));
            cardsLabel.setText(uniqueCards + " / " + CardCatalog.all().size());
            claimedLabel.setText(state.getCompletedChallenges().size() + " challenges claimed");
            XpProgressSnapshot progress = XpProgressSnapshot.from(state);
            updateProgress(packProgressLabel, packPercentLabel, packProgressBar,
                progress.getPackProgress(), progress.getPackInterval(), progress.getPackPercent());
            updateProgress(currencyProgressLabel, currencyPercentLabel, currencyProgressBar,
                progress.getCurrencyProgress(), progress.getCurrencyInterval(), progress.getCurrencyPercent());
            if (dialog != null && dialog.isVisible()) dialog.refreshData();
            revalidate();
            repaint();
        });
    }

    private static void updateProgress(JLabel value, JLabel percent, JProgressBar bar,
                                       int current, int target, int percentage)
    {
        value.setText(String.format("%,d / %,d XP", current, target));
        percent.setText(percentage + "%");
        bar.setValue(percentage);
    }

    public void hideDialog()
    {
        SwingUtilities.invokeLater(() -> { if (dialog != null) dialog.setVisible(false); });
    }

    private void showWelcomeIfNeeded()
    {
        DeckscapeState state = store.load();
        if (state.isWelcomeShown()) return;
        state.setWelcomeShown(true);
        store.save();
        SwingUtilities.invokeLater(this::showWelcome);
    }

    private void showWelcome()
    {
        new DeckscapeWelcomeDialog(this).setVisible(true);
    }

    public void disposeDialog()
    {
        SwingUtilities.invokeLater(() -> {
            if (dialog != null) dialog.dispose();
            dialog = null;
        });
    }

    public void setHandlers(DeckscapeDialog.OpenPackAction openPackAction,
                            DeckscapeDialog.PurchasePackAction purchasePackAction,
                            Runnable syncAction, Runnable beginPairingAction,
                            java.util.function.Consumer<Integer> soundPlayer)
    {
        this.openPackAction = openPackAction;
        this.purchasePackAction = purchasePackAction;
        this.syncAction = syncAction;
        this.beginPairingAction = beginPairingAction;
        this.soundPlayer = soundPlayer;
    }
}

package com.deckscape.runelite.ui;

import java.awt.Font;
import java.io.InputStream;

/** Fonts shared with the web client, bundled so cards render consistently offline. */
public final class DeckscapeFonts
{
    private static final String DISPLAY_RESOURCE = "/com/deckscape/runelite/fonts/IMFellEnglishSC-Regular.ttf";
    private static final Font DISPLAY = load(DISPLAY_RESOURCE, new Font("Serif", Font.PLAIN, 12));

    private DeckscapeFonts() { }

    public static Font display(float size)
    {
        return DISPLAY.deriveFont(Font.PLAIN, size);
    }

    private static Font load(String resource, Font fallback)
    {
        try (InputStream stream = DeckscapeFonts.class.getResourceAsStream(resource))
        {
            return stream == null ? fallback : Font.createFont(Font.TRUETYPE_FONT, stream);
        }
        catch (Exception ignored)
        {
            return fallback;
        }
    }
}

package com.deckscape.runelite.ui;

import com.deckscape.runelite.model.PackType;
import java.awt.Color;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

/**
 * Region and pack colour themes plus crest/backdrop resources, mirroring DeckscapeWeb's
 * styles.css (.region-* / .pack-* custom properties) and assets.tsx so both clients match.
 */
public final class RegionTheme
{
    public final Color color;
    public final Color deep;
    public final Color glow;
    public final String crest;
    public final String backdrop;

    private static final String REGIONS = "/com/deckscape/runelite/regions/";
    private static final Map<String, RegionTheme> BY_FACTION = new HashMap<>();
    private static final RegionTheme FALLBACK = new RegionTheme(0x765b35, 0x3c2b1b, 0xe7bc5e, null, null);

    static
    {
        region("misthalin", 0x2b69b7, 0x15305e, 0x9dcaff);
        region("karamja", 0x299464, 0x104b34, 0x97e6b8);
        region("asgarnia", 0x486fba, 0x273c68, 0xc3d6ff);
        region("kandarin", 0xa4443d, 0x58231f, 0xf1a798);
        region("fremennik", 0x89654e, 0x453126, 0xd8b394);
        region("morytania", 0x286c7d, 0x123a49, 0x8ed1db);
        region("desert", 0x2f9274, 0x154a3c, 0xa4e1c0);
        region("tirannwn", 0x8d949b, 0x454b52, 0xe0e5e8);
        region("wilderness", 0x5c6268, 0x292d31, 0xb8c0c6);
        region("kourend", 0x34799e, 0x173c55, 0x91cae8);
        region("varlamore", 0xe9a414, 0xbd5009, 0xffdc62);
        region("universal", 0x34456d, 0x18223b, 0x89a6ff);
    }

    private RegionTheme(int color, int deep, int glow, String crest, String backdrop)
    {
        this.color = new Color(color);
        this.deep = new Color(deep);
        this.glow = new Color(glow);
        this.crest = crest;
        this.backdrop = backdrop;
    }

    private static void region(String key, int color, int deep, int glow)
    {
        BY_FACTION.put(key, new RegionTheme(color, deep, glow,
            REGIONS + "crest_" + key + ".png",
            REGIONS + "backdrop_" + key + ".png"));
    }

    public static RegionTheme forFaction(String faction)
    {
        if (faction == null) return FALLBACK;
        return BY_FACTION.getOrDefault(faction.toLowerCase(Locale.ROOT), FALLBACK);
    }

    /** Faction packs reuse their region theme; the three XP packs have their own colours. */
    public static RegionTheme forPack(PackType type)
    {
        switch (type)
        {
            case GENERAL: return new RegionTheme(0x566989, 0x29344d, 0xb9c8e6, null, null);
            case COMBAT: return new RegionTheme(0x9a493c, 0x4a2623, 0xefae72, null, null);
            case SKILLING: return new RegionTheme(0x4b8b49, 0x244b2b, 0xa6db78, null, null);
            default: return forFaction(type.name().substring("FACTION_".length()));
        }
    }

    /** The picture at the centre of a pack: the XP packs' emblem art, or the region crest. */
    public static String packEmblem(PackType type)
    {
        switch (type)
        {
            case GENERAL: return "/com/deckscape/runelite/pack_general.png";
            case COMBAT: return "/com/deckscape/runelite/pack_combat.png";
            case SKILLING: return "/com/deckscape/runelite/pack_skilling.png";
            default: return forPack(type).crest;
        }
    }
}

package com.deckscape.runelite.ui;

import com.deckscape.runelite.model.DeckscapeCard;
import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.Timer;

public final class PackOpeningView extends JPanel
{
    public PackOpeningView(String packName, List<DeckscapeCard> cards, Consumer<Integer> soundPlayer, Runnable onDone)
    {
        setLayout(new BorderLayout(0, 12));
        setBackground(DeckscapePalette.PANEL_DARK);
        setBorder(BorderFactory.createEmptyBorder(15, 15, 15, 15));

        JLabel heading = new JLabel("<html><center><span style='font-size:18px; color:#ffd45e;'><b>" + packName + "</b></span><br><span style='font-size:13px; color:#a8a08a;'>Click each card to reveal your rewards!</span></center></html>", SwingConstants.CENTER);
        add(heading, BorderLayout.NORTH);

        // Layout cards in a single horizontal row (5 columns)
        JPanel grid = new JPanel(new GridLayout(1, 5, 12, 12));
        grid.setOpaque(false);

        List<RevealCardTile> tiles = new ArrayList<>();
        for (DeckscapeCard card : cards)
        {
            RevealCardTile tile = new RevealCardTile(card, soundPlayer);
            // Size cards beautifully for the larger 5-column layout
            tile.setPreferredSize(new Dimension(120, 185));
            tiles.add(tile);
            grid.add(tile);
        }

        // Wrap grid with horizontal glue to center it if smaller than window width
        JPanel centerWrapper = new JPanel();
        centerWrapper.setLayout(new BorderLayout());
        centerWrapper.setOpaque(false);
        centerWrapper.add(Box.createHorizontalGlue(), BorderLayout.WEST);
        centerWrapper.add(grid, BorderLayout.CENTER);
        centerWrapper.add(Box.createHorizontalGlue(), BorderLayout.EAST);

        add(centerWrapper, BorderLayout.CENTER);

        JButton done = button("Return to Packs");
        done.setPreferredSize(new java.awt.Dimension(200, 36));
        done.addActionListener(event -> onDone.run());

        JPanel southPanel = new JPanel();
        southPanel.setOpaque(false);
        southPanel.add(done);
        add(southPanel, BorderLayout.SOUTH);

        // Staggered card entry animations (slide/fade sequence)
        Timer arrivals = new Timer(180, null);
        final int[] index = {0};
        arrivals.addActionListener(event ->
        {
            if (index[0] >= tiles.size())
            {
                arrivals.stop();
                return;
            }
            tiles.get(index[0]++).setArrived(true);
            if (soundPlayer != null)
            {
                soundPlayer.accept(2581); // Subtle card place/swoosh sound
            }
        });
        arrivals.setInitialDelay(150);
        arrivals.start();
    }

    static JButton button(String text)
    {
        JButton button = new JButton(text);
        button.setFocusPainted(false);
        button.setForeground(DeckscapePalette.INK);
        button.setBackground(DeckscapePalette.BRASS);
        button.setFont(button.getFont().deriveFont(java.awt.Font.BOLD, 13f));
        button.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(new java.awt.Color(111, 75, 17), 2),
            BorderFactory.createEmptyBorder(6, 16, 6, 16)));
        return button;
    }
}

package com.deckscape.runelite;

import com.deckscape.runelite.model.DeckscapeState;
import com.google.gson.Gson;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

@Singleton
public final class DeckscapeStore
{
    private static final String GROUP = "deckscape";
    private static final String KEY = "prototypeState";
    private final ConfigManager configManager;
    private final Gson gson;
    private DeckscapeState state;

    @Inject
    public DeckscapeStore(ConfigManager configManager, Gson gson)
    {
        this.configManager = configManager;
        this.gson = gson;
    }

    public DeckscapeState load()
    {
        if (state != null) return state;
        String json = configManager.getConfiguration(GROUP, KEY);
        try
        {
            state = json == null || json.isEmpty() ? new DeckscapeState() : gson.fromJson(json, DeckscapeState.class);
        }
        catch (RuntimeException ignored)
        {
            state = new DeckscapeState();
        }
        if (state == null) state = new DeckscapeState();
        return state;
    }

    public void save()
    {
        configManager.setConfiguration(GROUP, KEY, gson.toJson(load()));
    }
}

package com.deckscape.runelite;

import com.deckscape.runelite.model.PackType;
import com.deckscape.runelite.ui.CardPainter;
import com.deckscape.runelite.ui.DeckscapeImages;
import com.deckscape.runelite.ui.DeckscapePalette;
import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayDeque;
import java.util.Deque;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;

/**
 * Compact in-game reward toast on the bundled OSRS-style panel art (background.png),
 * queued so simultaneous XP rolls are never hidden.
 */
@Singleton
public final class PackRewardOverlay extends Overlay
{
    private static final long INTRO = 420L;
    private static final long HOLD = RewardPopupLayout.linger(2500L);
    private static final long OUTRO = 520L;
    private static final long TOTAL = INTRO + HOLD + OUTRO;

    private final Client client;
    private final DeckscapeConfig config;
    private final Deque<Reward> queue = new ArrayDeque<>();
    private Reward active;
    private long startedAt;
    private BufferedImage packIcon;

    @Inject
    public PackRewardOverlay(Client client, DeckscapeConfig config)
    {
        this.client = client;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(OverlayPriority.HIGH);
    }

    public synchronized void showPack(PackType type)
    {
        queue.addLast(Reward.pack(type));
        if (active == null) advance();
    }

    public synchronized void showCoins(int amount)
    {
        if (amount <= 0) return;
        queue.addLast(new Reward("COINS FOUND!", "+" + amount + " Coins", "Added to your wallet",
            "/com/deckscape/runelite/ui/wallet_coins.png", null));
        if (active == null) advance();
    }

    public synchronized void showStardust(int amount)
    {
        if (amount <= 0) return;
        queue.addLast(new Reward("STARDUST FOUND!", "+" + amount + " Stardust", "Added to your wallet",
            "/com/deckscape/runelite/ui/wallet_stardust.png", null));
        if (active == null) advance();
    }

    private void advance()
    {
        active = queue.pollFirst();
        startedAt = active == null ? 0L : System.currentTimeMillis();
        if (active == null) packIcon = null;
        else if (active.packType != null) packIcon = CardPainter.packImage(active.packType,
            RewardPopupLayout.scale(22), RewardPopupLayout.scale(32));
        else packIcon = fitIcon(DeckscapeImages.load(active.iconResource),
            RewardPopupLayout.scale(32), RewardPopupLayout.scale(32));
    }

    @Override
    public synchronized Dimension render(Graphics2D graphics)
    {
        if (!config.packRewardPopup() || active == null) return null;
        long elapsed = System.currentTimeMillis() - startedAt;
        if (elapsed >= TOTAL)
        {
            advance();
            return null;
        }
        float alpha = elapsed < INTRO ? ease(elapsed / (float) INTRO)
            : elapsed > INTRO + HOLD ? 1f - ease((elapsed - INTRO - HOLD) / (float) OUTRO) : 1f;
        float rise = 1f - ease(Math.min(1f, elapsed / (float) INTRO));
        int width = Math.min(RewardPopupLayout.WIDTH, RewardPopupLayout.viewportWidth(client) - 12);
        int height = RewardPopupLayout.HEIGHT;
        int x = RewardPopupLayout.centerX(client) - width / 2;
        int y = RewardPopupLayout.TOP + Math.round(rise * -14f);

        graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        graphics.setComposite(AlphaComposite.SrcOver.derive(alpha));

        BufferedImage panel = DeckscapeImages.load("/background.png");
        if (panel != null)
        {
            graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
            graphics.drawImage(panel, x, y, width, height, null);
        }
        else
        {
            graphics.setColor(new Color(8, 7, 5, 225));
            graphics.fillRoundRect(x, y, width, height, 12, 12);
        }

        if (packIcon != null)
        {
            graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
            graphics.drawImage(packIcon, x + RewardPopupLayout.scale(7), y + (height - packIcon.getHeight()) / 2, null);
        }
        int textX = x + RewardPopupLayout.scale(7)
            + (packIcon == null ? 0 : packIcon.getWidth() + RewardPopupLayout.scale(5));
        graphics.setColor(new Color(10, 8, 5, 145));
        graphics.fillRoundRect(textX - RewardPopupLayout.scale(3), y + RewardPopupLayout.scale(7),
            x + width - textX - RewardPopupLayout.scale(6), RewardPopupLayout.scale(45),
            RewardPopupLayout.scale(4), RewardPopupLayout.scale(4));
        drawText(graphics, active.title, textX, y + RewardPopupLayout.scale(19),
            new Font("SansSerif", Font.BOLD, RewardPopupLayout.scale(9)), new Color(255, 231, 151));
        drawText(graphics, active.detail, textX, y + RewardPopupLayout.scale(34),
            new Font("SansSerif", Font.BOLD, RewardPopupLayout.scale(8)), Color.WHITE);
        drawText(graphics, active.footer, textX, y + RewardPopupLayout.scale(48),
            new Font("SansSerif", Font.BOLD, RewardPopupLayout.scale(7)), new Color(235, 220, 184));
        graphics.setComposite(AlphaComposite.SrcOver);
        return null;
    }

    private static void drawText(Graphics2D g, String text, int x, int baseline, Font font, Color color)
    {
        g.setFont(font);
        g.setColor(new Color(0, 0, 0, 230));
        g.drawString(text, x + 1, baseline + 1);
        g.setColor(color);
        g.drawString(text, x, baseline);
    }

    private static BufferedImage fitIcon(BufferedImage source, int maximumWidth, int maximumHeight)
    {
        if (source == null) return null;
        double scale = Math.min(maximumWidth / (double) source.getWidth(), maximumHeight / (double) source.getHeight());
        int width = Math.max(1, (int) Math.round(source.getWidth() * scale));
        int height = Math.max(1, (int) Math.round(source.getHeight() * scale));
        BufferedImage result = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = result.createGraphics();
        try
        {
            graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
            graphics.drawImage(source, 0, 0, width, height, null);
        }
        finally { graphics.dispose(); }
        return result;
    }

    private static final class Reward
    {
        private final String title;
        private final String detail;
        private final String footer;
        private final String iconResource;
        private final PackType packType;

        private Reward(String title, String detail, String footer, String iconResource, PackType packType)
        {
            this.title = title;
            this.detail = detail;
            this.footer = footer;
            this.iconResource = iconResource;
            this.packType = packType;
        }

        private static Reward pack(PackType type)
        {
            return new Reward("PACK UNLOCKED!", "+1 " + type.getDisplayName(), "Open it in Deckscape", null, type);
        }
    }

    private static float ease(float value)
    {
        float t = Math.max(0f, Math.min(1f, value));
        return 1f - (1f - t) * (1f - t) * (1f - t);
    }
}

package com.deckscape.runelite.challenge;

import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.GraphicChanged;

@Singleton
public final class ElementalStrikeTracker
{
    private static final int CAST_WINDOW_TICKS = 8;
    private final Client client;
    private PendingCast pendingCast;
    private Consumer<VerifiedRuneLiteChallengeEvent> completionHandler;

    @Inject
    public ElementalStrikeTracker(Client client)
    {
        this.client = client;
    }

    public void setCompletionHandler(Consumer<VerifiedRuneLiteChallengeEvent> completionHandler)
    {
        this.completionHandler = completionHandler;
    }

    public void onGraphicChanged(GraphicChanged event)
    {
        if (event.getActor() != client.getLocalPlayer()) return;
        int graphicId = client.getLocalPlayer().getGraphic();
        ElementalSpell spell = ElementalSpell.fromGraphic(graphicId);
        if (spell != null)
        {
            pendingCast = new PendingCast(spell, client.getTickCount(), client.getLocalPlayer().getInteracting());
        }
    }

    public void onHitsplatApplied(HitsplatApplied event)
    {
        PendingCast cast = pendingCast;
        if (cast == null || client.getTickCount() - cast.tick > CAST_WINDOW_TICKS)
        {
            pendingCast = null;
            return;
        }
        if (!event.getHitsplat().isMine() || cast.target == null || event.getActor() != cast.target) return;

        int damage = event.getHitsplat().getAmount();
        pendingCast = null;

        if (damage >= 16 && completionHandler != null)
        {
            completionHandler.accept(VerifiedRuneLiteChallengeEvent.strike(cast.spell.contractName, damage));
        }
    }

    private enum ElementalSpell
    {
        WIND("WIND_STRIKE", 90),
        WATER("WATER_STRIKE", 93),
        EARTH("EARTH_STRIKE", 96),
        FIRE("FIRE_STRIKE", 99);

        private final String contractName;
        private final int castGfx;

        ElementalSpell(String contractName, int castGfx)
        {
            this.contractName = contractName;
            this.castGfx = castGfx;
        }

        private static ElementalSpell fromGraphic(int gfxId)
        {
            for (ElementalSpell spell : values())
            {
                if (spell.castGfx == gfxId) return spell;
            }
            return null;
        }
    }

    private static final class PendingCast
    {
        private final ElementalSpell spell;
        private final int tick;
        private final Actor target;

        private PendingCast(ElementalSpell spell, int tick, Actor target)
        {
            this.spell = spell;
            this.tick = tick;
            this.target = target;
        }
    }
}

package com.deckscape.runelite.challenge;

import com.google.gson.JsonObject;
import java.time.Instant;
import java.util.UUID;

/** Authenticated observation sent through the persisted server outbox. */
public final class VerifiedRuneLiteChallengeEvent
{
    public static final int VERSION = 1;
    private final int version = VERSION;
    private final String eventId = UUID.randomUUID().toString();
    private final String kind;
    private final String observedAt = Instant.now().toString();
    private final int quantity;
    private final int damage;
    private final String spell;

    private VerifiedRuneLiteChallengeEvent(String kind, int quantity, int damage, String spell)
    {
        this.kind = kind;
        this.quantity = quantity;
        this.damage = damage;
        this.spell = spell;
    }

    public static VerifiedRuneLiteChallengeEvent observed(RuneLiteChallenge challenge)
    {
        return new VerifiedRuneLiteChallengeEvent(challenge.getKind(), 1, 0, null);
    }

    public static VerifiedRuneLiteChallengeEvent quantity(RuneLiteChallenge challenge, int quantity)
    {
        return new VerifiedRuneLiteChallengeEvent(challenge.getKind(), Math.max(1, quantity), 0, null);
    }

    public static VerifiedRuneLiteChallengeEvent strike(String spell, int damage)
    {
        return new VerifiedRuneLiteChallengeEvent(RuneLiteChallenge.STRIKE_HIT.getKind(), 1, damage, spell);
    }

    public int getVersion() { return version; }
    public String getEventId() { return eventId; }
    public String getKind() { return kind; }
    public String getObservedAt() { return observedAt; }
    public int getQuantity() { return quantity; }
    public int getDamage() { return damage; }
    public String getSpell() { return spell; }

    public JsonObject toPayload()
    {
        JsonObject payload = new JsonObject();
        payload.addProperty("version", version);
        payload.addProperty("kind", kind);
        payload.addProperty("observedAt", observedAt);
        if (RuneLiteChallenge.PURE_ESSENCE.getKind().equals(kind)
            || RuneLiteChallenge.RUNE_KITESHIELD.getKind().equals(kind)) payload.addProperty("quantity", quantity);
        if (RuneLiteChallenge.STRIKE_HIT.getKind().equals(kind))
        {
            payload.addProperty("damage", damage);
            if (spell != null) payload.addProperty("spell", spell);
        }
        return payload;
    }
}

