package com.deckscape.runelite.challenge;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.ItemID;
import net.runelite.api.Skill;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.VarbitID;

/**
 * Correlates inventory/equipment changes with game-owned XP, chat, and varbit evidence.
 * Rewards are still validated, de-duplicated, and granted by the Deckscape service.
 */
@Singleton
public final class GoldenFrameChallengeTracker
{
    private static final int EVIDENCE_WINDOW_TICKS = 2;

    private static final Set<Integer> MAX_CAPES = setOf(
        ItemID.MAX_CAPE, ItemID.FIRE_MAX_CAPE, ItemID.SARADOMIN_MAX_CAPE, ItemID.ZAMORAK_MAX_CAPE,
        ItemID.GUTHIX_MAX_CAPE, ItemID.ACCUMULATOR_MAX_CAPE, ItemID.ARDOUGNE_MAX_CAPE,
        ItemID.INFERNAL_MAX_CAPE, ItemID.IMBUED_SARADOMIN_MAX_CAPE, ItemID.IMBUED_ZAMORAK_MAX_CAPE,
        ItemID.IMBUED_GUTHIX_MAX_CAPE, ItemID.ASSEMBLER_MAX_CAPE, ItemID.MYTHICAL_MAX_CAPE,
        ItemID.MASORI_ASSEMBLER_MAX_CAPE, ItemID.DIZANAS_MAX_CAPE);
    private static final Set<Integer> DIZANAS_QUIVERS = setOf(
        ItemID.DIZANAS_QUIVER_UNCHARGED, ItemID.DIZANAS_QUIVER_L_UNCHARGED,
        ItemID.DIZANAS_QUIVER, ItemID.DIZANAS_QUIVER_L,
        ItemID.BLESSED_DIZANAS_QUIVER, ItemID.BLESSED_DIZANAS_QUIVER_L);
    private static final Set<Integer> QUEST_CAPES = setOf(ItemID.QUEST_POINT_CAPE, ItemID.QUEST_POINT_CAPE_T);

    private final Client client;
    private final Set<String> observedOnce = new HashSet<>();
    private Consumer<VerifiedRuneLiteChallengeEvent> handler;
    private int lastPureEssence = -1;
    private int lastRuneKiteshields = -1;
    private int pendingPureEssence;
    private int pendingPureTick = -100;
    private int pendingRuneKiteshields;
    private int pendingRuneTick = -100;
    private int miningEvidenceTick = -100;
    private int smithingEvidenceTick = -100;

    @Inject
    public GoldenFrameChallengeTracker(Client client)
    {
        this.client = client;
    }

    public void setCompletionHandler(Consumer<VerifiedRuneLiteChallengeEvent> handler)
    {
        this.handler = handler;
    }

    public void resetSession()
    {
        observedOnce.clear();
        lastPureEssence = -1;
        lastRuneKiteshields = -1;
        pendingPureEssence = 0;
        pendingRuneKiteshields = 0;
        miningEvidenceTick = smithingEvidenceTick = -100;
    }

    public void onStatChanged(Skill skill, int gained)
    {
        if (gained <= 0) return;
        int tick = client.getTickCount();
        if (skill == Skill.MINING)
        {
            miningEvidenceTick = tick;
            flushPureEssence(tick);
        }
        else if (skill == Skill.SMITHING)
        {
            smithingEvidenceTick = tick;
            flushRuneKiteshields(tick);
        }
    }

    public void onChatMessage(ChatMessage event)
    {
        String message = event.getMessage() == null ? "" : event.getMessage().toLowerCase();
        int tick = client.getTickCount();
        if (message.contains("mine some pure essence"))
        {
            miningEvidenceTick = tick;
            flushPureEssence(tick);
        }
        if (message.contains("rune kiteshield") && (message.contains("hammer") || message.contains("smith")))
        {
            smithingEvidenceTick = tick;
            flushRuneKiteshields(tick);
        }
    }

    public void onItemContainerChanged(ItemContainerChanged event)
    {
        if (event.getContainerId() == InventoryID.EQUIPMENT.getId())
        {
            inspectEquipment(event.getItemContainer());
            return;
        }
        if (event.getContainerId() != InventoryID.INVENTORY.getId()) return;

        ItemContainer inventory = event.getItemContainer();
        int tick = client.getTickCount();
        int pure = inventory.count(ItemID.PURE_ESSENCE);
        int kiteshields = inventory.count(ItemID.RUNE_KITESHIELD);
        if (lastPureEssence >= 0 && pure > lastPureEssence)
        {
            pendingPureEssence += pure - lastPureEssence;
            pendingPureTick = tick;
        }
        if (lastRuneKiteshields >= 0 && kiteshields > lastRuneKiteshields)
        {
            pendingRuneKiteshields += kiteshields - lastRuneKiteshields;
            pendingRuneTick = tick;
        }
        lastPureEssence = pure;
        lastRuneKiteshields = kiteshields;
        flushPureEssence(tick);
        flushRuneKiteshields(tick);
    }

    public void onGameTick()
    {
        int tick = client.getTickCount();
        ItemContainer inventory = client.getItemContainer(InventoryID.INVENTORY);
        if (inventory != null && lastPureEssence < 0)
        {
            lastPureEssence = inventory.count(ItemID.PURE_ESSENCE);
            lastRuneKiteshields = inventory.count(ItemID.RUNE_KITESHIELD);
        }
        ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
        if (equipment != null) inspectEquipment(equipment);
        if (Math.abs(tick - pendingPureTick) > EVIDENCE_WINDOW_TICKS) pendingPureEssence = 0;
        if (Math.abs(tick - pendingRuneTick) > EVIDENCE_WINDOW_TICKS) pendingRuneKiteshields = 0;
        if (client.getVarbitValue(VarbitID.KANDARIN_DIARY_ELITE_COMPLETE) > 0)
            emitOnce(RuneLiteChallenge.KANDARIN_ELITE);
    }

    private void inspectEquipment(ItemContainer equipment)
    {
        if (equipment == null) return;
        Set<Integer> equipped = new HashSet<>();
        for (Item item : equipment.getItems()) if (item.getId() > 0) equipped.add(item.getId());
        if (equipped.contains(ItemID.LEDERHOSEN_TOP)
            && equipped.contains(ItemID.LEDERHOSEN_SHORTS)
            && equipped.contains(ItemID.LEDERHOSEN_HAT)) emitOnce(RuneLiteChallenge.LEDERHOSEN);
        if (containsAny(equipped, MAX_CAPES)) emitOnce(RuneLiteChallenge.MAX_CAPE);
        if (containsAny(equipped, DIZANAS_QUIVERS)) emitOnce(RuneLiteChallenge.DIZANAS_QUIVER);
        if (containsAny(equipped, QUEST_CAPES)) emitOnce(RuneLiteChallenge.QUEST_CAPE);
    }

    private void flushPureEssence(int tick)
    {
        if (pendingPureEssence > 0 && Math.abs(tick - pendingPureTick) <= EVIDENCE_WINDOW_TICKS
            && Math.abs(tick - miningEvidenceTick) <= EVIDENCE_WINDOW_TICKS)
        {
            emit(VerifiedRuneLiteChallengeEvent.quantity(RuneLiteChallenge.PURE_ESSENCE, pendingPureEssence));
            pendingPureEssence = 0;
        }
    }

    private void flushRuneKiteshields(int tick)
    {
        if (pendingRuneKiteshields > 0 && Math.abs(tick - pendingRuneTick) <= EVIDENCE_WINDOW_TICKS
            && Math.abs(tick - smithingEvidenceTick) <= EVIDENCE_WINDOW_TICKS)
        {
            emit(VerifiedRuneLiteChallengeEvent.quantity(RuneLiteChallenge.RUNE_KITESHIELD, pendingRuneKiteshields));
            pendingRuneKiteshields = 0;
        }
    }

    private void emitOnce(RuneLiteChallenge challenge)
    {
        if (observedOnce.add(challenge.getKind())) emit(VerifiedRuneLiteChallengeEvent.observed(challenge));
    }

    private void emit(VerifiedRuneLiteChallengeEvent event)
    {
        if (handler != null) handler.accept(event);
    }

    private static boolean containsAny(Set<Integer> equipped, Set<Integer> expected)
    {
        for (Integer itemId : expected) if (equipped.contains(itemId)) return true;
        return false;
    }

    private static Set<Integer> setOf(Integer... values)
    {
        return new HashSet<>(Arrays.asList(values));
    }
}

package com.deckscape.runelite.challenge;

import java.util.Collection;
import java.util.EnumSet;
import net.runelite.api.GameState;
import net.runelite.api.WorldType;

/** Keeps rewards on persistent, main-game worlds and out of temporary or no-save modes. */
public final class WorldEligibility
{
    private static final EnumSet<WorldType> DISALLOWED = EnumSet.of(
        WorldType.DEADMAN,
        WorldType.SEASONAL,
        WorldType.PVP,
        WorldType.BOUNTY,
        WorldType.HIGH_RISK,
        WorldType.LAST_MAN_STANDING,
        WorldType.PVP_ARENA,
        WorldType.NOSAVE_MODE,
        WorldType.TOURNAMENT_WORLD,
        WorldType.BETA_WORLD,
        WorldType.QUEST_SPEEDRUNNING,
        WorldType.FRESH_START_WORLD
    );

    private WorldEligibility() {}

    public static boolean isEligible(GameState gameState, Collection<WorldType> worldTypes)
    {
        if (gameState != GameState.LOGGED_IN || worldTypes == null) return false;
        for (WorldType type : worldTypes)
        {
            if (DISALLOWED.contains(type)) return false;
        }
        return true;
    }
}

package com.deckscape.runelite;

import com.deckscape.runelite.ui.DeckscapeImages;
import com.deckscape.runelite.ui.DeckscapePalette;
import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;

/** A high-priority milestone ceremony following the tracker → server → notifier pipeline. */
@Singleton
public final class ChallengeCompletionOverlay extends Overlay
{
    private static final long SWEEP = 480L;
    private static final long OPEN = 620L;
    private static final long HOLD = RewardPopupLayout.linger(3400L);
    private static final long OUT = 700L;
    private static final long TOTAL = SWEEP + OPEN + HOLD + OUT;
    private final Client client;
    private final DeckscapeConfig config;
    private long startedAt = -1L;
    private String title = "";
    private String reward = "";

    @Inject
    public ChallengeCompletionOverlay(Client client, DeckscapeConfig config)
    {
        this.client = client;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(OverlayPriority.HIGH);
    }

    public synchronized void showCompletion(String title, String reward)
    {
        this.title = title;
        this.reward = reward;
        this.startedAt = System.currentTimeMillis();
    }

    @Override
    public synchronized Dimension render(Graphics2D graphics)
    {
        if (startedAt < 0L || !config.completionPopup()) return null;
        long elapsed = System.currentTimeMillis() - startedAt;
        if (elapsed >= TOTAL) { startedAt = -1L; return null; }
        float sweep = ease(Math.min(1f, elapsed / (float) SWEEP));
        float open = elapsed <= SWEEP ? 0f : ease(Math.min(1f, (elapsed - SWEEP) / (float) OPEN));
        float alpha = elapsed > TOTAL - OUT ? 1f - ease((elapsed - (TOTAL - OUT)) / (float) OUT) : 1f;
        int viewportWidth = RewardPopupLayout.viewportWidth(client);
        int centerX = RewardPopupLayout.centerX(client);
        int centerY = RewardPopupLayout.TOP;
        int width = Math.min(RewardPopupLayout.WIDTH, viewportWidth - 12);
        int fullHeight = RewardPopupLayout.HEIGHT;
        int height = Math.round(fullHeight * open);

        Graphics2D g = (Graphics2D) graphics.create();
        try
        {
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g.setComposite(AlphaComposite.SrcOver.derive(alpha));
            int lineWidth = Math.round((viewportWidth - 36) * sweep);
            g.setPaint(new java.awt.GradientPaint(centerX - lineWidth / 2f, 0, new Color(115, 69, 13, 0), centerX, 0, DeckscapePalette.GOLD, true));
            g.fillRect(centerX - lineWidth / 2, centerY - 2, lineWidth, 4);
            if (height < 6) return null;

            int x = centerX - width / 2;
            int y = centerY;
            BufferedImage panel = DeckscapeImages.load("/background.png");
            if (panel != null)
            {
                g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
                g.drawImage(panel, x, y, width, height, null);
            }
            else
            {
                g.setColor(new Color(8, 7, 5, 238));
                g.fillRoundRect(x, y, width, height, 10, 10);
            }
            if (open < .72f) return null;

            float textAlpha = Math.min(1f, (open - .72f) / .28f);
            g.setComposite(AlphaComposite.SrcOver.derive(alpha * textAlpha));
            g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
            BufferedImage art = DeckscapeImages.load("/com/deckscape/runelite/cards/fire_strike.png");
            int artSize = RewardPopupLayout.scale(34);
            if (art != null)
            {
                g.setColor(new Color(255, 202, 72, 90));
                g.fillRoundRect(x + RewardPopupLayout.scale(7), y + (fullHeight - artSize) / 2,
                    artSize, artSize, RewardPopupLayout.scale(5), RewardPopupLayout.scale(5));
                g.drawImage(art, x + RewardPopupLayout.scale(9),
                    y + (fullHeight - artSize) / 2 + RewardPopupLayout.scale(2),
                    artSize - RewardPopupLayout.scale(4), artSize - RewardPopupLayout.scale(4), null);
            }
            int textX = x + RewardPopupLayout.scale(7) + artSize + RewardPopupLayout.scale(6);
            int textWidth = x + width - textX - RewardPopupLayout.scale(6);
            g.setColor(new Color(10, 8, 5, 150));
            g.fillRoundRect(textX - RewardPopupLayout.scale(3), y + RewardPopupLayout.scale(6),
                textWidth + RewardPopupLayout.scale(3), RewardPopupLayout.scale(48),
                RewardPopupLayout.scale(4), RewardPopupLayout.scale(4));
            drawText(g, "CHALLENGE COMPLETE", textX, y + RewardPopupLayout.scale(15),
                new Font("SansSerif", Font.BOLD, RewardPopupLayout.scale(7)), new Color(255, 231, 151));
            drawFittedText(g, title, textX, y + RewardPopupLayout.scale(29), textWidth,
                new Font("SansSerif", Font.BOLD, RewardPopupLayout.scale(9)), Color.WHITE);
            drawFittedText(g, reward, textX, y + RewardPopupLayout.scale(41), textWidth,
                new Font("SansSerif", Font.BOLD, RewardPopupLayout.scale(6)), new Color(235, 220, 184));
            drawText(g, "Saved to Deckscape", textX, y + RewardPopupLayout.scale(52),
                new Font("SansSerif", Font.BOLD, RewardPopupLayout.scale(6)), new Color(210, 190, 145));
        }
        finally { g.dispose(); }
        return null;
    }

    private static void drawFittedText(Graphics2D graphics, String text, int x, int baseline,
                                       int maximumWidth, Font preferred, Color color)
    {
        Font font = preferred;
        while (font.getSize() > RewardPopupLayout.scale(6)
            && graphics.getFontMetrics(font).stringWidth(text) > maximumWidth)
            font = font.deriveFont((float) font.getSize() - 1f);
        drawText(graphics, text, x, baseline, font, color);
    }

    private static void drawText(Graphics2D graphics, String text, int x, int baseline, Font font, Color color)
    {
        graphics.setFont(font);
        graphics.setColor(new Color(0, 0, 0, 230));
        graphics.drawString(text, x + 1, baseline + 1);
        graphics.setColor(color);
        graphics.drawString(text, x, baseline);
    }

    private static float ease(float value)
    {
        float t = Math.max(0f, Math.min(1f, value));
        return t < .5f ? 4f * t * t * t : 1f - (float) Math.pow(-2f * t + 2f, 3) / 2f;
    }
}

package com.deckscape.runelite;

import com.deckscape.runelite.model.PackType;
import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.concurrent.CompletableFuture;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

@Slf4j
@Singleton
public final class DeckscapeSyncClient
{
    private static final MediaType JSON = MediaType.get("application/json; charset=utf-8");
    private static final String ECONOMY_URL = "https://ahqakitttmbcpxdpdlkx.supabase.co/functions/v1/economy";
    private static final String PUBLISHABLE_KEY = "sb_publishable_cJq6CMLU68GNrfxe5XUPyQ_VRNCuZBX";
    private final OkHttpClient httpClient;
    private final Gson gson;

    public static final class HttpException extends Exception
    {
        private final int statusCode;

        private HttpException(int statusCode, String message)
        {
            super(message);
            this.statusCode = statusCode;
        }

        public boolean isPermanentValidationFailure()
        {
            return statusCode == 400 || statusCode == 422;
        }

        public boolean isAuthenticationFailure()
        {
            return statusCode == 401 || statusCode == 403;
        }
    }

    @Inject
    public DeckscapeSyncClient(OkHttpClient httpClient, Gson gson)
    {
        this.httpClient = httpClient;
        this.gson = gson;
    }

    public CompletableFuture<JsonObject> request(String deviceToken, String action, JsonObject payload)
    {
        CompletableFuture<JsonObject> future = new CompletableFuture<>();
        if (deviceToken == null || deviceToken.isEmpty())
        {
            future.completeExceptionally(new Exception("Sync is not configured or not linked."));
            return future;
        }

        JsonObject bodyJson = payload != null ? payload : new JsonObject();
        bodyJson.addProperty("action", action);

        RequestBody body = RequestBody.create(JSON, gson.toJson(bodyJson));
        Request request = new Request.Builder()
            .url(ECONOMY_URL)
            .post(body)
            .addHeader("apikey", PUBLISHABLE_KEY)
            .addHeader("X-Deckscape-Device-Token", deviceToken)
            .build();

        httpClient.newCall(request).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException e)
            {
                future.completeExceptionally(e);
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException
            {
                try (Response r = response)
                {
                    if (!r.isSuccessful())
                    {
                        String err = r.body() != null ? r.body().string() : "Request failed";
                        try {
                            JsonObject errObj = gson.fromJson(err, JsonObject.class);
                            if (errObj.has("error")) {
                                future.completeExceptionally(new HttpException(r.code(), errObj.get("error").getAsString()));
                                return;
                            }
                        } catch (Exception ignored) {}
                        future.completeExceptionally(new HttpException(r.code(), "HTTP " + r.code() + ": " + err));
                        return;
                    }
                    String bodyStr = r.body() != null ? r.body().string() : "{}";
                    JsonObject json = gson.fromJson(bodyStr, JsonObject.class);
                    future.complete(json);
                }
                catch (Exception e)
                {
                    future.completeExceptionally(e);
                }
            }
        });

        return future;
    }

    public CompletableFuture<JsonObject> startPairing()
    {
        JsonObject body = new JsonObject();
        body.addProperty("action", "start_runelite_pairing");
        return publicRequest(body);
    }

    public CompletableFuture<JsonObject> finishPairing(String pairingCode, String deviceToken)
    {
        JsonObject body = new JsonObject();
        body.addProperty("action", "finish_runelite_pairing");
        body.addProperty("pairingCode", pairingCode == null ? "" : pairingCode.trim().toUpperCase());
        body.addProperty("deviceToken", deviceToken == null ? "" : deviceToken);
        return publicRequest(body);
    }

    private CompletableFuture<JsonObject> publicRequest(JsonObject bodyJson)
    {
        CompletableFuture<JsonObject> future = new CompletableFuture<>();
        Request request = new Request.Builder().url(ECONOMY_URL).post(RequestBody.create(JSON, gson.toJson(bodyJson)))
            .addHeader("apikey", PUBLISHABLE_KEY).build();
        httpClient.newCall(request).enqueue(jsonCallback(future));
        return future;
    }

    private Callback jsonCallback(CompletableFuture<JsonObject> future)
    {
        return new Callback()
        {
            @Override public void onFailure(Call call, IOException e) { future.completeExceptionally(e); }
            @Override public void onResponse(Call call, Response response) throws IOException
            {
                try (Response r = response)
                {
                    String body = r.body() == null ? "{}" : r.body().string();
                    JsonObject json = gson.fromJson(body, JsonObject.class);
                    if (!r.isSuccessful()) { future.completeExceptionally(new Exception(json != null && json.has("error") ? json.get("error").getAsString() : "HTTP " + r.code())); return; }
                    future.complete(json == null ? new JsonObject() : json);
                }
                catch (Exception e) { future.completeExceptionally(e); }
            }
        };
    }
}

